mapper.select:
SELECT expire_type AS name, COUNT(*) AS value FROM ( SELECT CASE WHEN expire_date <= DATE_ADD(NOW(), INTERVAL 1 MONTH) THEN 'expireInOneMonth' WHEN expire_date <= DATE_ADD(NOW(), INTERVAL 3 MONTH) THEN 'expireInThreeMonth' ELSE 'safe' END AS expire_type FROM ( SELECT COALESCE( expiration_date, DATE_ADD(production_date, INTERVAL validity_mon MONTH) ) AS expire_date FROM wkf_inventory_item WHERE is_deleted = 0 AND inventory_status_enum = 'ACTIVE' AND (expiration_date IS NOT NULL OR (production_date IS NOT NULL AND validity_mon IS NOT NULL))
AND item_table = #{itemTable}
) AS calc ) AS temp GROUP BY expire_type
